import{_ as a,c as o,o as t,a2 as s}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1784988047000}'),n={name:"guide/faq.md"};function i(p,e,r,d,l,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Q: What is Minesweeper?</p><p>A: Minesweeper is the classic mine-clearing puzzle game, reimagined for modern devices. Tap to reveal tiles, long-press to flag mines, and use logic to clear the board safely. It&#39;s a universal app supporting iPhone, iPad, and Mac.</p><p>Q: Which devices are supported?</p><p>A: Minesweeper is a universal app optimized for iPhone, iPad, and Mac with native controls and crisp Retina display graphics. It requires iOS/iPadOS 15.0 or later and macOS 15.0 (Sequoia) or later. One purchase works on all supported devices.</p><p>Q: How do I download and install Minesweeper?</p><p>A: Download Minesweeper from the App Store: <a href="https://apps.apple.com/app/id6793471840" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793471840</a> — the universal app works on iPhone, iPad, and Mac.</p><p>Q: Does Minesweeper need an internet connection?</p><p>A: No. Minesweeper has full offline support — no internet needed, no data usage. The only network access is an optional &quot;More Apps&quot; section in Settings that fetches a list of sibling apps; this can be ignored and does not affect gameplay.</p><p>Q: Are there ads or in-app purchases?</p><p>A: No. Minesweeper is completely ad-free with no pop-ups, no in-app purchases, and no interruptions. Just pure, focused gameplay.</p><p>Q: What difficulty levels are available?</p><p>A: Three difficulty levels, with board sizes optimized per device:</p><ul><li><strong>Beginner</strong> — iPhone: 10×14 (14 mines), iPad: 16×16 (18 mines), Mac: 9×9 (10 mines)</li><li><strong>Intermediate</strong> — iPhone: 14×22 (45 mines), iPad: 18×16 (55 mines), Mac: 16×16 (40 mines)</li><li><strong>Expert</strong> — iPhone: 16×30 (99 mines), iPad: 18×24 (99 mines), Mac: 30×16 (99 mines)</li></ul><p>Q: Is my game data uploaded anywhere?</p><p>A: No. Minesweeper is 100% offline — your settings and game state are stored locally on your device. Nothing is uploaded or transmitted, except the optional &quot;More Apps&quot; feature which only fetches a list of sibling apps.</p><p>Q: Does Minesweeper save best times or scores?</p><p>A: Minesweeper shows a detailed scoreboard at the end of each game (time, 3BV difficulty metric, click breakdown), but does not persist best times across sessions. Each game is a fresh challenge.</p><p>Q: How do I update the app?</p><p>A: App Store users receive updates automatically. To check manually, open the App Store and go to your Account → Updates section.</p><p>Q: How do I report bugs or request features?</p><p>A: Open an issue in the project repository and include your device type, iOS/macOS version, Minesweeper version, reproduction steps, and screenshots if available.</p><p>Q: Can I customize the game?</p><p>A: Yes. In Settings you can switch between 25 languages at runtime, adjust game resolution on Mac, toggle flagging mode (no-flag mode), and turn sound effects on or off.</p><p>Q: What are the keyboard shortcuts on Mac?</p><p>A: <code>⌘N</code> for a new game, <code>⌘1</code>/<code>⌘2</code>/<code>⌘3</code> for Beginner/Intermediate/Expert, and <code>⌘⇧R</code> to reveal all mines (practice mode).</p><p>If you need more answers, please open an issue in the repository or consult the full documentation.</p>',27)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
